custom_css:
.sc-tw *,.sc-tw *::before,.sc-tw *::after{
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }.sc-tw :root{
      --aurora-deep: oklch(25% 0.15 300);
      --aurora-teal: oklch(75% 0.12 180);
      --aurora-pink: oklch(65% 0.2 330);
      --aurora-mid: oklch(35% 0.18 290);
      --aurora-glow: oklch(80% 0.14 185);
      --glass-bg: oklch(28% 0.08 290 / 0.35);
      --glass-border: oklch(75% 0.1 200 / 0.18);
      --glass-shine: oklch(90% 0.05 200 / 0.12);
      --text-primary: oklch(96% 0.02 200);
      --text-secondary: oklch(78% 0.06 210);
      --text-muted: oklch(60% 0.05 240);
      --font-weight: 300;
    }.sc-tw html{
      scroll-behavior: smooth;
    }.sc-tw{
      font-family: 'Inter', system-ui, sans-serif;
      font-variation-settings: 'wght' var(--font-weight);
      background: var(--aurora-deep);
      color: var(--text-primary);
      min-height: 100vh;
      overflow-x: hidden;
      cursor: none;
    }.sc-tw .cursor{
      position: fixed;
      width: 12px;
      height: 12px;
      background: var(--aurora-teal);
      border-radius: 50%;
      pointer-events: none;
      z-index: 9999;
      mix-blend-mode: screen;
      transition: transform 0.15s ease, opacity 0.3s ease;
      transform: translate(-50%, -50%);
    }.sc-tw .cursor-ring{
      position: fixed;
      width: 40px;
      height: 40px;
      border: 1px solid oklch(75% 0.12 180 / 0.5);
      border-radius: 50%;
      pointer-events: none;
      z-index: 9998;
      transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), width 0.3s ease, height 0.3s ease, border-color 0.3s ease;
      transform: translate(-50%, -50%);
    }.sc-tw body:has(a:hover) .cursor-ring,.sc-tw body:has(button:hover) .cursor-ring{
      width: 60px;
      height: 60px;
      border-color: oklch(65% 0.2 330 / 0.6);
    }.sc-tw ::selection{
      background: oklch(65% 0.2 330 / 0.4);
      color: var(--text-primary);
    }.sc-tw .scene{
      position: relative;
      min-height: 100vh;
    }.sc-tw .bg-gradient{
      position: fixed;
      inset: 0;
      background:
        radial-gradient(ellipse 80% 60% at 20% 50%, oklch(35% 0.18 290 / 0.8) 0%, transparent 70%),
        radial-gradient(ellipse 60% 80% at 80% 20%, oklch(40% 0.15 220 / 0.6) 0%, transparent 60%),
        radial-gradient(ellipse 70% 50% at 60% 80%, oklch(30% 0.2 330 / 0.5) 0%, transparent 60%),
        oklch(18% 0.1 290);
      z-index: 0;
    }.sc-tw .aurora-layer{
      position: fixed;
      inset: 0;
      z-index: 1;
      pointer-events: none;
      overflow: hidden;
    }.sc-tw .aurora-band{
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      animation: aurora-drift 20s ease-in-out infinite;
      mix-blend-mode: screen;
      opacity: 0.35;
    }.sc-tw .aurora-band:nth-child(1){
      width: 120%;
      height: 40%;
      top: 10%;
      left: -20%;
      background: linear-gradient(90deg,
          transparent 0%,
          oklch(75% 0.12 180 / 0.6) 30%,
          oklch(65% 0.15 200 / 0.4) 60%,
          transparent 100%);
      animation-delay: 0s;
      animation-duration: 25s;
    }.sc-tw .aurora-band:nth-child(2){
      width: 100%;
      height: 35%;
      top: 25%;
      left: 10%;
      background: linear-gradient(90deg,
          transparent 0%,
          oklch(65% 0.2 330 / 0.4) 20%,
          oklch(75% 0.12 200 / 0.3) 70%,
          transparent 100%);
      animation-delay: -8s;
      animation-duration: 30s;
    }.sc-tw .aurora-band:nth-child(3){
      width: 80%;
      height: 30%;
      top: 5%;
      right: -10%;
      background: linear-gradient(90deg,
          transparent 0%,
          oklch(55% 0.18 260 / 0.5) 40%,
          oklch(65% 0.15 310 / 0.3) 80%,
          transparent 100%);
      animation-delay: -15s;
      animation-duration: 22s;
    }

    @keyframes aurora-drift {0%,100%{
        transform: translateX(0) translateY(0) scaleY(1);
        opacity: 0.35;
      }25%{
        transform: translateX(5%) translateY(3%) scaleY(1.2);
        opacity: 0.45;
      }50%{
        transform: translateX(-3%) translateY(-2%) scaleY(0.9);
        opacity: 0.3;
      }75%{
        transform: translateX(8%) translateY(1%) scaleY(1.1);
        opacity: 0.4;
      }
    }.sc-tw .video-portal{
      position: fixed;
      top: 50%;
      right: 5%;
      transform: translateY(-50%);
      width: clamp(280px, 35vw, 520px);
      height: clamp(380px, 55vh, 720px);
      z-index: 2;
      border-radius: 28px 8px 28px 8px;
      overflow: hidden;
      mask-image: radial-gradient(ellipse 80% 90% at 60% 50%, black 30%, transparent 100%);
      -webkit-mask-image: radial-gradient(ellipse 80% 90% at 60% 50%, black 30%, transparent 100%);
    }.sc-tw .video-portal video{
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0.7;
      filter: saturate(1.4) brightness(0.85);
    }.sc-tw .video-portal-glow{
      position: fixed;
      top: 50%;
      right: 3%;
      transform: translateY(-50%);
      width: clamp(320px, 40vw, 580px);
      height: clamp(420px, 65vh, 800px);
      z-index: 1;
      background: radial-gradient(ellipse at center,
          oklch(55% 0.15 200 / 0.2) 0%,
          oklch(45% 0.18 260 / 0.1) 50%,
          transparent 80%);
      border-radius: 40px;
      filter: blur(40px);
      pointer-events: none;
    }.sc-tw .video-fallback-bg{
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 60% 60% at 40% 40%, oklch(60% 0.15 185) 0%, transparent 70%),
        radial-gradient(ellipse 50% 50% at 70% 70%, oklch(55% 0.2 310) 0%, transparent 60%),
        oklch(30% 0.12 240);
      animation: portal-shimmer 8s ease-in-out infinite;
    }

    @keyframes portal-shimmer {0%,100%{
        filter: brightness(0.9) hue-rotate(0deg);
      }50%{
        filter: brightness(1.1) hue-rotate(15deg);
      }
    }.sc-tw .main-content{
      position: relative;
      z-index: 10;
      min-height: 100vh;
      padding: 0 max(2rem, 5vw);
      max-width: 55%;
    }.sc-tw nav{
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 100;
      padding: 1.5rem max(2rem, 5vw);
      display: flex;
      align-items: center;
      justify-content: space-between;
      backdrop-filter: blur(40px) saturate(1.5);
      background: oklch(20% 0.1 290 / 0.4);
      border-bottom: 1px solid var(--glass-border);
    }.sc-tw .nav-logo{
      font-size: clamp(1rem, 1.4vw, 1.2rem);
      font-variation-settings: 'wght' 600;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      color: var(--text-primary);
      text-decoration: none;
      display: flex;
      align-items: center;
      gap: 0.75rem;
    }.sc-tw .nav-logo-mark{
      width: 28px;
      height: 28px;
      background: conic-gradient(from 180deg,
          var(--aurora-teal),
          var(--aurora-pink),
          var(--aurora-teal));
      border-radius: 6px;
      animation: logo-spin 12s linear infinite;
    }

    @keyframes logo-spin {to{
        transform: rotate(360deg);
      }
    }.sc-tw .nav-links{
      display: flex;
      gap: 2.5rem;
      list-style: none;
    }.sc-tw .nav-links a{
      color: var(--text-secondary);
      text-decoration: none;
      font-size: 0.8rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      transition: color 0.3s ease;
      position: relative;
    }.sc-tw .nav-links a::after{
      content: '';
      position: absolute;
      bottom: -4px;
      left: 0;
      width: 0;
      height: 1px;
      background: var(--aurora-teal);
      transition: width 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }.sc-tw .nav-links a:hover{
      color: var(--text-primary);
    }.sc-tw .nav-links a:hover::after{
      width: 100%;
    }.sc-tw .nav-cta{
      padding: 0.5rem 1.25rem;
      border: 1px solid var(--glass-border);
      border-radius: 100px;
      color: var(--text-primary);
      text-decoration: none;
      font-size: 0.75rem;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      backdrop-filter: blur(20px);
      background: var(--glass-shine);
      transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
      position: relative;
      overflow: hidden;
    }.sc-tw .nav-cta::before{
      content: '';
      position: absolute;
      inset: -100%;
      background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(75% 0.12 180 / 0.3) 0%,
          transparent 60%);
      transition: opacity 0.3s ease;
      opacity: 0;
    }.sc-tw .nav-cta:hover::before{
      opacity: 1;
    }.sc-tw .nav-cta:hover{
      border-color: oklch(75% 0.12 180 / 0.5);
      box-shadow: 0 0 30px oklch(75% 0.12 180 / 0.15);
    }.sc-tw .hero{
      padding-top: clamp(8rem, 18vh, 14rem);
      padding-bottom: 4rem;
    }.sc-tw .hero-eyebrow{
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-bottom: 2rem;
      opacity: 0;
      animation: fade-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.2s forwards;
    }.sc-tw .eyebrow-line{
      width: 40px;
      height: 1px;
      background: var(--aurora-teal);
    }.sc-tw .eyebrow-text{
      font-size: 0.7rem;
      letter-spacing: 0.4em;
      text-transform: uppercase;
      color: var(--aurora-teal);
      font-variation-settings: 'wght' 500;
    }.sc-tw .hero-title{
      font-size: clamp(2.8rem, 6vw, 5.5rem);
      line-height: 0.95;
      letter-spacing: -0.04em;
      margin-bottom: 1.5rem;
      font-variation-settings: 'wght' 200;
    }.sc-tw .hero-title-line{
      display: block;
      overflow: hidden;
    }.sc-tw .hero-title-line span{
      display: inline-block;
      opacity: 0;
      transform: translateY(100%);
      animation: slide-up 1s cubic-bezier(0.16, 1, 0.3, 1) forwards;
    }.sc-tw .hero-title-line:nth-child(1) span{
      animation-delay: 0.4s;
    }.sc-tw .hero-title-line:nth-child(2) span{
      animation-delay: 0.55s;
    }.sc-tw .hero-title-line:nth-child(3) span{
      animation-delay: 0.7s;
    }.sc-tw .hero-title .accent{
      color: transparent;
      -webkit-text-stroke: 1px oklch(75% 0.12 180 / 0.7);
      font-variation-settings: 'ital' 1, 'wght' 100;
    }.sc-tw .hero-sub{
      font-size: clamp(0.85rem, 1.2vw, 1rem);
      color: var(--text-secondary);
      line-height: 1.7;
      max-width: 38ch;
      margin-bottom: 3rem;
      font-variation-settings: 'wght' 300;
      opacity: 0;
      animation: fade-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) 0.9s forwards;
    }.sc-tw .hero-actions{
      display: flex;
      gap: 1.25rem;
      align-items: center;
      opacity: 0;
      animation: fade-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.1s forwards;
    }.sc-tw .btn-primary{
      position: relative;
      padding: 0.9rem 2.5rem;
      background: transparent;
      border: 0;
      border-radius: 100px;
      color: var(--aurora-deep);
      font-family: inherit;
      font-size: 0.8rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      cursor: none;
      overflow: hidden;
      font-variation-settings: 'wght' 500;
      isolation: isolate;
    }.sc-tw .btn-primary-bg{
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg, var(--aurora-teal), var(--aurora-glow));
      border-radius: 100px;
      transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
    }.sc-tw .btn-primary:hover .btn-primary-bg{
      transform: scale(1.03);
    }.sc-tw .btn-primary-liquid{
      position: absolute;
      inset: 0;
      border-radius: 100px;
      background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(90% 0.08 180 / 0.6) 0%,
          transparent 50%);
      opacity: 0;
      transition: opacity 0.3s ease;
    }.sc-tw .btn-primary:hover .btn-primary-liquid{
      opacity: 1;
    }.sc-tw .btn-primary span{
      position: relative;
      z-index: 1;
    }.sc-tw .btn-ghost{
      position: relative;
      padding: 0.9rem 2rem;
      background: transparent;
      border: 1px solid var(--glass-border);
      border-radius: 100px;
      color: var(--text-secondary);
      font-family: inherit;
      font-size: 0.8rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      cursor: none;
      font-variation-settings: 'wght' 400;
      transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1);
      display: flex;
      align-items: center;
      gap: 0.75rem;
      overflow: hidden;
    }.sc-tw .btn-ghost::before{
      content: '';
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at var(--mx, 50%) var(--my, 50%),
          oklch(75% 0.12 180 / 0.1) 0%,
          transparent 60%);
      opacity: 0;
      transition: opacity 0.3s ease;
    }.sc-tw .btn-ghost:hover{
      color: var(--text-primary);
      border-color: oklch(75% 0.12 180 / 0.4);
    }.sc-tw .btn-ghost:hover::before{
      opacity: 1;
    }.sc-tw .stats-row{
      display: flex;
      gap: 3rem;
      margin-top: 5rem;
      padding-top: 3rem;
      border-top: 1px solid var(--glass-border);
      opacity: 0;
      animation: fade-up 0.8s cubic-bezier(0.16, 1, 0.3, 1) 1.3s forwards;
    }.sc-tw .stat-item{}.sc-tw .stat-value{
      font-size: clamp(1.8rem, 3vw, 2.4rem);
      font-variation-settings: 'wght' 200;
      letter-spacing: -0.04em;
      color: var(--text-primary);
      line-height: 1;
      margin-bottom: 0.4rem;
    }.sc-tw .stat-unit{
      font-size: 0.7em;
      color: var(--aurora-teal);
      font-variation-settings: 'wght' 400;
    }.sc-tw .stat-label{
      font-size: 0.68rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      color: var(--text-muted);
    }.sc-tw .bento-section{
      padding: 6rem 0;
      position: relative;
      z-index: 10;
    }.sc-tw .section-header{
      margin-bottom: 3rem;
    }.sc-tw .section-eyebrow{
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-bottom: 1rem;
    }.sc-tw .section-title{
      font-size: clamp(2rem, 3.5vw, 3rem);
      font-variation-settings: 'wght' 200;
      letter-spacing: -0.03em;
      line-height: 1.1;
    }.sc-tw .bento-grid{
      display: grid;
      grid-template-columns: repeat(12, 1fr);
      grid-template-rows: auto;
      gap: 1rem;
    }.sc-tw .bento-card{
      position: relative;
      background: var(--glass-bg);
      backdrop-filter: blur(100px) saturate(1.8);
      -webkit-backdrop-filter: blur(100px) saturate(1.8);
      border: 1px solid var(--glass-border);
      border-radius: 20px;
      overflow: hidden;
      transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1), box-shadow 0.4s ease;
      container-type: inline-size;
    }.sc-tw .bento-card::before{
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(135deg,
          oklch(90% 0.05 200 / 0.08) 0%,
          transparent 50%,
          oklch(65% 0.1 300 / 0.05) 100%);
      pointer-events: none;
      z-index: 1;
    }.sc-tw .bento-card::after{
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      height: 1px;
      background: linear-gradient(90deg,
          transparent,
          oklch(90% 0.05 200 / 0.3),
          transparent);
      z-index: 2;
    }.sc-tw .bento-card:hover{
      transform: translateY(-4px) scale(1.005);
      box-shadow:
        0 32px 80px oklch(15% 0.15 290 / 0.5),
        inset 0 1px 0 oklch(90% 0.05 200 / 0.15),
        inset 0 -1px 0 oklch(50% 0.1 270 / 0.1),
        0 0 0 1px oklch(75% 0.12 180 / 0.1);
    }.sc-tw .bento-card-inner{
      position: relative;
      z-index: 3;
      height: 100%;
      padding: 1.75rem;
    }.sc-tw .bc-hero{
      grid-column: span 7;
      min-height: 380px;
    }.sc-tw .bc-tall{
      grid-column: span 5;
      min-height: 380px;
    }.sc-tw .bc-wide{
      grid-column: span 8;
      min-height: 200px;
    }.sc-tw .bc-sm{
      grid-column: span 4;
      min-height: 200px;
    }.sc-tw .bc-med{
      grid-column: span 6;
      min-height: 260px;
    }.sc-tw .bc-med-r{
      grid-column: span 6;
      min-height: 260px;
    }

    @container (max-width: 300px) {.sc-tw .card-meta{
        display: none;
      }.sc-tw .card-title{
        font-size: 1rem;
      }
    }.sc-tw .card-eyebrow{
      font-size: 0.65rem;
      letter-spacing: 0.3em;
      text-transform: uppercase;
      color: var(--aurora-teal);
      margin-bottom: 0.75rem;
      font-variation-settings: 'wght' 500;
    }.sc-tw .card-title{
      font-size: clamp(1.2rem, 2.5cqw, 1.8rem);
      font-variation-settings: 'wght' 300;
      letter-spacing: -0.02em;
      line-height: 1.2;
      margin-bottom: 0.75rem;
    }.sc-tw .card-desc{
      font-size: 0.82rem;
      color: var(--text-secondary);
      line-height: 1.65;
      font-variation-settings: 'wght' 300;
    }.sc-tw .card-meta{
      display: flex;
      align-items: center;
      gap: 1rem;
      margin-top: auto;
      padding-top: 1.5rem;
    }.sc-tw .price-tag{
      font-size: 1.6rem;
      font-variation-settings: 'wght' 200;
      letter-spacing: -0.04em;
      color: var(--text-primary);
    }.sc-tw .price-sub{
      font-size: 0.7rem;
      color: var(--text-muted);
      letter-spacing: 0.1em;
    }.sc-tw .badge{
      display: inline-flex;
      align-items: center;
      gap: 0.4rem;
      padding: 0.3rem 0.75rem;
      border-radius: 100px;
      font-size: 0.65rem;
      letter-spacing: 0.15em;
      text-transform: uppercase;
      font-variation-settings: 'wght' 500;
    }.sc-tw .badge-teal{
      background: oklch(75% 0.12 180 / 0.15);
      color: var(--aurora-teal);
      border: 1px solid oklch(75% 0.12 180 / 0.25);
    }.sc-tw .badge-pink{
      background: oklch(65% 0.2 330 / 0.12);
      color: oklch(75% 0.15 330);
      border: 1px solid oklch(65% 0.2 330 / 0.25);
    }.sc-tw .badge-dot{
      width: 5px;
      height: 5px;
      border-radius: 50%;
      background: currentColor;
      animation: pulse-dot 2s ease-in-out infinite;
    }

    @keyframes pulse-dot {0%,100%{
        opacity: 1;
        transform: scale(1);
      }50%{
        opacity: 0.5;
        transform: scale(0.7);
      }
    }.sc-tw .card-visual{
      position: absolute;
      inset: 0;
      pointer-events: none;
    }.sc-tw .card-orb{
      position: absolute;
      border-radius: 50%;
      filter: blur(60px);
    }.sc-tw .orb-teal{
      width: 200px;
      height: 200px;
      background: oklch(75% 0.12 180 / 0.25);
      animation: orb-float 8s ease-in-out infinite;
    }.sc-tw .orb-pink{
      width: 150px;
      height: 150px;
      background: oklch(65% 0.2 330 / 0.2);
      animation: orb-float 6s ease-in-out infinite reverse;
    }.sc-tw .orb-purple{
      width: 180px;
      height: 180px;
      background: oklch(55% 0.18 280 / 0.3);
      animation: orb-float 10s ease-in-out infinite;
    }

    @keyframes orb-float {0%,100%{
        transform: translate(0, 0) scale(1);
      }33%{
        transform: translate(10%, -15%) scale(1.1);
      }66%{
        transform: translate(-8%, 10%) scale(0.95);
      }
    }.sc-tw .temp-display{
      font-size: clamp(3rem, 8cqw, 6rem);
      font-variation-settings: 'wght' 100;
      letter-spacing: -0.06em;
      line-height: 1;
      color: var(--text-primary);
      margin: 0.5rem 0;
    }.sc-tw .temp-unit{
      font-size: 0.4em;
      color: var(--text-muted);
      vertical-align: super;
    }.sc-tw .spec-grid{
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 0.75rem;
      margin-top: 1rem;
    }.sc-tw .spec-item{
      padding: 0.75rem;
      background: oklch(30% 0.1 290 / 0.4);
      border-radius: 10px;
      border: 1px solid oklch(70% 0.08 200 / 0.1);
    }.sc-tw .spec-val{
      font-size: 1.1rem;
      font-variation-settings: 'wght' 300;
      letter-spacing: -0.02em;
      color: var(--text-primary);
    }.sc-tw .spec-key{
      font-size: 0.62rem;
      letter-spacing: 0.2em;
      text-transform: uppercase;
      color: var(--text-muted);
      margin-top: 0.2rem;
    }.sc-tw .gear-showcase{
      display: flex;
      flex-direction: column;
      height: 100%;
      gap: 1rem;
    }.sc-tw .gear-item{
      flex: 1;
      display: flex;
      align-items: center;
      gap: 1rem;
      padding: 1rem;
      background: oklch(28% 0.08 290 / 0.4);
      border-radius: 12px;
      border: 1px solid var(--glass-border);
      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);
      cursor: none;
